   { size_t mo=0,ml=0; int tw=16; if(stbtt__vl_raw_table_bounds(info,"maxp",&mo,&ml)&&ml>=18&&ttULONG(info->data+mo)>=0x00010000)tw=ttUSHORT(info->data+mo+16); if(tw<1)tw=1;if(tw>1024)tw=1024;c.twilight_count=tw; }
