/**
 * @file
 * Common types used in decoder and encoder API.
 */

#ifndef VLTT__BR_BROTLI_COMMON_TYPES_H_
#define VLTT__BR_BROTLI_COMMON_TYPES_H_

#include <stddef.h>  /* IWYU pragma: export */

#if defined(_MSC_VER) && (_MSC_VER < 1600)
typedef __int8 int8_t;
typedef unsigned __int8 uint8_t;
typedef __int16 int16_t;
typedef unsigned __int16 uint16_t;
typedef __int32 int32_t;
typedef unsigned __int32 uint32_t;
typedef unsigned __int64 uint64_t;
typedef __int64 int64_t;
#else
#include <stdint.h>  /* IWYU pragma: export */
#endif  /* defined(_MSC_VER) && (_MSC_VER < 1600) */

/**
 * A portable @c bool replacement.
 *
 * ::VLTT__BR_BROTLI_BOOL is a "documentation" type: actually it is @c int, but in API it
 * denotes a type, whose only values are ::VLTT__BR_BROTLI_TRUE and ::VLTT__BR_BROTLI_FALSE.
 *
 * ::VLTT__BR_BROTLI_BOOL values passed to vltt__br_Brotli should either be ::VLTT__BR_BROTLI_TRUE or
 * ::VLTT__BR_BROTLI_FALSE, or be a result of ::TO_BROTLI_BOOL macros.
 *
 * ::VLTT__BR_BROTLI_BOOL values returned by vltt__br_Brotli should not be tested for equality
 * with @c true, @c false, ::VLTT__BR_BROTLI_TRUE, ::VLTT__BR_BROTLI_FALSE, but rather should be
 * evaluated, for example: @code{.cpp}
 * if (SomeBrotliFunction(encoder, VLTT__BR_BROTLI_TRUE) &&
 *     !OtherBrotliFunction(decoder, VLTT__BR_BROTLI_FALSE)) {
 *   bool x = !!YetAnotherBrotliFunction(encoder, TO_BROLTI_BOOL(2 * 2 == 4));
 *   DoSomething(x);
 * }
 * @endcode
 */
#define VLTT__BR_BROTLI_BOOL int
/** Portable @c true replacement. */
#define VLTT__BR_BROTLI_TRUE 1
/** Portable @c false replacement. */
#define VLTT__BR_BROTLI_FALSE 0
/** @c bool to ::VLTT__BR_BROTLI_BOOL conversion macros. */
#define TO_BROTLI_BOOL(X) (!!(X) ? VLTT__BR_BROTLI_TRUE : VLTT__BR_BROTLI_FALSE)

#define VLTT__BR_BROTLI_MAKE_UINT64_T(high, low) ((((uint64_t)(high)) << 32) | low)

#define VLTT__BR_BROTLI_UINT32_MAX (~((uint32_t)0))
#define VLTT__BR_BROTLI_SIZE_MAX (~((size_t)0))

/**
 * Allocating function pointer type.
 *
 * @param opaque custom memory manager handle provided by client
 * @param size requested memory region size; can not be @c 0
 * @returns @c 0 in the case of failure
 * @returns a valid pointer to a memory region of at least @p size bytes
 *          long otherwise
 */
typedef void* (*vltt__br_brotli_alloc_func)(void* opaque, size_t size);

/**
 * Deallocating function pointer type.
 *
 * This function @b SHOULD do nothing if @p address is @c 0.
 *
 * @param opaque custom memory manager handle provided by client
 * @param address memory region pointer returned by ::vltt__br_brotli_alloc_func, or @c 0
 */
typedef void (*vltt__br_brotli_free_func)(void* opaque, void* address);

#endif  /* VLTT__BR_BROTLI_COMMON_TYPES_H_ */

