/* Version definition. */

#ifndef VLTT__BR_BROTLI_COMMON_VERSION_H_
#define VLTT__BR_BROTLI_COMMON_VERSION_H_

/* Compose 3 components into a single number. In a hexadecimal representation
   B and C components occupy exactly 3 digits. */
#define VLTT__BR_BROTLI_MAKE_HEX_VERSION(A, B, C) ((A << 24) | (B << 12) | C)

/* Those macros should only be used when library is compiled together with
   the client. If library is dynamically linked, use vltt__br_BrotliDecoderVersion and
   vltt__br_BrotliEncoderVersion methods. */

#define VLTT__BR_BROTLI_VERSION_MAJOR 1
#define VLTT__BR_BROTLI_VERSION_MINOR 2
#define VLTT__BR_BROTLI_VERSION_PATCH 0

#define VLTT__BR_BROTLI_VERSION VLTT__BR_BROTLI_MAKE_HEX_VERSION(                     \
  VLTT__BR_BROTLI_VERSION_MAJOR, VLTT__BR_BROTLI_VERSION_MINOR, VLTT__BR_BROTLI_VERSION_PATCH)

/* This macro is used by build system to produce Libtool-friendly soname. See
   https://www.gnu.org/software/libtool/manual/html_node/Libtool-versioning.html
   Version evolution rules:
    - interfaces added (or change is compatible)      -> current+1:0:age+1
    - interfaces removed (or changed is incompatible) -> current+1:0:0
    - interfaces not changed                          -> current:revision+1:age
 */

#define VLTT__BR_BROTLI_ABI_CURRENT  3
#define VLTT__BR_BROTLI_ABI_REVISION 0
#define VLTT__BR_BROTLI_ABI_AGE      2

#if VLTT__BR_BROTLI_VERSION_MAJOR != (VLTT__BR_BROTLI_ABI_CURRENT - VLTT__BR_BROTLI_ABI_AGE)
#error ABI/API version inconsistency
#endif

#if VLTT__BR_BROTLI_VERSION_MINOR != VLTT__BR_BROTLI_ABI_AGE
#error ABI/API version inconsistency
#endif

#if VLTT__BR_BROTLI_VERSION_PATCH != VLTT__BR_BROTLI_ABI_REVISION
#error ABI/API version inconsistency
#endif

#endif  /* VLTT__BR_BROTLI_COMMON_VERSION_H_ */

