static int vltt__w2_reserve(vltt__w2buf *b, size_t add)
{
   size_t need, cap;
   unsigned char *p;
   if (add > SIZE_MAX - b->n) return 0;
   need = b->n + add;
   if (need <= b->cap) return 1;
   cap = b->cap ? b->cap : 256;
   while (cap < need) { if (cap > STBTT_MAX_FONT_SIZE/2) { cap = need; break; } cap *= 2; }
   if (cap > STBTT_MAX_FONT_SIZE) return 0;
   p = (unsigned char*)realloc(b->p, cap);
   if (!p) return 0;
   b->p = p; b->cap = cap; return 1;
}
static int vltt__w2_put(vltt__w2buf *b, const void *p, size_t n) { if (!vltt__w2_reserve(b,n)) return 0; memcpy(b->p+b->n,p,n); b->n+=n; return 1; }
