      size_t a=idx?(size_t)ttULONG(loca+i*4):(size_t)ttUSHORT(loca+i*2)*2u;
      size_t b=idx?(size_t)ttULONG(loca+(i+1)*4):(size_t)ttUSHORT(loca+(i+1)*2)*2u;
