   {int n=ttUSHORT(data+cmap+2);for(int i=0;i<n;i++){stbtt_uint32 r=cmap+4u+(stbtt_uint32)i*8u;if((size_t)r+8>size)break;int platform=ttUSHORT(data+r),enc=ttUSHORT(data+r+2);stbtt_uint32 sub=cmap+ttULONG(data+r+4);if((size_t)sub+2>size)continue;int fmt=ttUSHORT(data+sub),score=stbtt__cmap_score(platform,enc,fmt);if(score>best){best=score;bestmap=sub;}}}
