   memcpy(work,"\x00\x01\x00\x00",4);vltt__stream_write_u16(work+4,(uint16_t)n);vltt__stream_write_u16(work+6,0);vltt__stream_write_u16(work+8,0);vltt__stream_write_u16(work+10,0);
   cur=(dir_size+3u)&~(size_t)3u;n=0;
