   if(tag==0x74746366u){n=((uint32_t)h[8]<<24)|((uint32_t)h[9]<<16)|((uint32_t)h[10]<<8)|h[11];if(index>=(int)n||12u+(uint64_t)(index+1)*4u>source_size)return 0;if(vltt__stream_read_exact_raw(read,user,12u+(uint64_t)index*4u,o,4)!=4)return 0;off=((uint32_t)o[0]<<24)|((uint32_t)o[1]<<16)|((uint32_t)o[2]<<8)|o[3];if((uint64_t)off>=source_size)return 0;*offset=off;return 1;}
